import math
from functools import reduce

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def lcm_list(numbers):
    return reduce(lcm, numbers)

def is_weakly_increasing(n, start_k, end_k):
    for k in range(start_k, end_k):
        x_k = lcm_list(range(k, k + n))
        x_next = lcm_list(range(k + 1, k + 1 + n))
        if x_next <= x_k:
            return False, k
    return True, None

results = []
for n in range(1, 11):
    increasing, fail_k = is_weakly_increasing(n, 500, 1000)
    results.append((n, increasing, fail_k))

print(results)

